// root holds the current values; every getter reads through it.
type root struct {
	cur *engine.Snapshot[values]
	w   *engine.Writer[values] // nil for commands without the store
	st  *store.Store
	// pinned marks a Snapshot's root, whose Close does nothing.
	pinned bool
}

