// Key names a mutable setting, for Change.Has.
type Key string

// The mutable settings.
const (
	KeyThemeBrandColor    Key = "theme.brand_color"
	KeyThemeDangerColor   Key = "theme.danger_color"
	KeyThemeWarningColor  Key = "theme.warning_color"
	KeyThemeSuccessColor  Key = "theme.success_color"
	KeyThemeInfoColor     Key = "theme.info_color"
	KeyThemeFontSans      Key = "theme.font_sans"
	KeyThemeFontMono      Key = "theme.font_mono"
	KeyThemeRadius        Key = "theme.radius"
	KeyI18nDefaultLocale  Key = "i18n.default_locale"
	KeyCFPClosed          Key = "cfp.closed"
	KeyCFPMaxTalks        Key = "cfp.max_talks"
	KeyCFPDefaultLevel    Key = "cfp.default_level"
	KeyCFPDefaultDuration Key = "cfp.default_duration"
)

// Change lists the settings whose values a write changed, for OnChange.
type Change struct{ keys []Key }

// Has reports whether any of keys changed.
func (c Change) Has(keys ...Key) bool {
	for _, k := range keys {
		for _, ck := range c.keys {
			if k == ck {
				return true
			}
		}
	}
	return false
}

// Keys returns the settings that changed, in the order the schema declares
// them.
func (c Change) Keys() []Key { return append([]Key(nil), c.keys...) }

