// Store is the admin API over the Serve command's settings, for a
// settings dashboard or other generic code.
func (c *Serve) Store() *store.Store { return c.r.st }

// Update applies the changes fn makes to mutable settings, all together or
// none: the whole configuration is validated, the changes are stored with
// their history, and then the getters return the new values. Options such
// as cfgx.By and cfgx.Reason are kept in the history.
func (c *Serve) Update(ctx context.Context, fn func(u *Update) error, opts ...cfgx.WriteOption) error {
	return c.r.w.Write(ctx, func(e *engine.Edits[values]) error { return fn(&Update{e: e}) }, opts...)
}

// OnChange calls fn after an update changes settings, with the keys whose
// values changed. Calls run one at a time, in the order the updates were
// made, after the getters return the new values.
func (c *Serve) OnChange(fn func(Change)) {
	c.r.w.OnChange(func(paths []string) {
		keys := make([]Key, len(paths))
		for i, p := range paths {
			keys[i] = Key(p)
		}
		fn(Change{keys: keys})
	})
}

// Snapshot returns the Serve configuration as it is now, for a
// consistent read of several settings: its getters never change. It shares
// the store: its Store and Update work on the live settings, and its Close
// does nothing.
func (c *Serve) Snapshot() *Serve {
	s := newServe(engine.NewSnapshot(c.r.cur.Load()), c.r.w, c.args)
	s.r.pinned = true
	return s
}

// Close closes the store. ServeCommand calls it after run returns;
// LoadServe callers must call it. A Snapshot's Close does nothing.
func (c *Serve) Close() error {
	if c.r.pinned || c.r.w == nil {
		return nil
	}
	return c.r.w.Close()
}

// ServeCommand binds the Serve configuration to cmd: it registers the
// command's flags and sets its RunE, which loads the configuration and calls run.
func ServeCommand(cmd *cobra.Command, run func(context.Context, *Serve) error) *cobra.Command {
	return engine.Command(cmd, &app, "Serve", keysServe, newServe, run)
}

// LoadServe loads the Serve configuration without cobra, from the
// config file, the environment and the arguments that options such as
// cfgx.WithArgs, cfgx.WithEnv and cfgx.WithFile give.
// It opens the store, which the caller must close with Close.
func LoadServe(ctx context.Context, opts ...cfgx.Option) (*Serve, error) {
	return engine.LoadCommand(ctx, &app, "Serve", keysServe, newServe, opts...)
}

