// LoadSeed loads the Seed configuration without cobra, from the
// config file, the environment and the arguments that options such as
// cfgx.WithArgs, cfgx.WithEnv and cfgx.WithFile give.
// It opens the store, which the caller must close with Close.
func LoadSeed(ctx context.Context, opts ...cfgx.Option) (*Seed, error) {
	return engine.LoadCommand(ctx, &app, "Seed", keysSeed, newSeed, opts...)
}
